<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/certificate-auth.php';
$user=fleet_cert_require_user();fleet_cert_require_permission($user,'page.trips');$db=fleet_db();
try{
 $teams=$db->query("SELECT DISTINCT h.id horse_asset_id,h.primary_identifier horse,tr.id trailer_asset_id,tr.primary_identifier trailer,d.id driver_id,d.full_name driver,aa.id attachment_id,da.id driver_assignment_id,r.horse_inspection_id,r.trailer_inspection_id,r.driver_fitness_check_id FROM combination_readiness_approvals r JOIN asset_attachments aa ON aa.id=r.attachment_id AND aa.attached_to IS NULL JOIN assets h ON h.id=aa.head_asset_id AND h.is_active=1 JOIN assets tr ON tr.id=aa.trailer_asset_id AND tr.is_active=1 JOIN asset_driver_assignments da ON da.id=r.driver_assignment_id AND da.assigned_to IS NULL JOIN drivers d ON d.id=da.driver_id AND d.is_active=1 JOIN vehicle_inspections hi ON hi.id=r.horse_inspection_id AND hi.result='PASS' AND hi.critical_defects=0 AND hi.checked_at>=NOW()-INTERVAL 24 HOUR JOIN vehicle_inspections ti ON ti.id=r.trailer_inspection_id AND ti.result='PASS' AND ti.critical_defects=0 AND ti.checked_at>=NOW()-INTERVAL 24 HOUR JOIN driver_fitness_checks fc ON fc.id=r.driver_fitness_check_id AND fc.result='PASS' AND fc.licence_checked=1 AND fc.rested=1 AND fc.fit_to_drive=1 AND fc.licence_expiry IS NOT NULL AND fc.licence_expiry>=CURDATE() AND fc.checked_at>=NOW()-INTERVAL 24 HOUR WHERE r.status='APPROVED' AND r.horse_inspection_id=(SELECT MAX(id) FROM vehicle_inspections WHERE asset_id=h.id) AND r.trailer_inspection_id=(SELECT MAX(id) FROM vehicle_inspections WHERE asset_id=tr.id) AND r.driver_fitness_check_id=(SELECT MAX(id) FROM driver_fitness_checks WHERE driver_id=d.id) AND r.decided_at>=NOW()-INTERVAL 24 HOUR AND NOT EXISTS(SELECT 1 FROM maintenance_logs ml WHERE ml.asset_id IN (h.id,tr.id) AND ml.resolved_at IS NULL) AND NOT EXISTS(SELECT 1 FROM maintenance_work_orders mw WHERE mw.asset_id IN (h.id,tr.id) AND mw.status IN ('OPEN','IN_PROGRESS','REPAIR_COMPLETE')) ORDER BY h.primary_identifier,tr.primary_identifier,d.full_name")->fetchAll();
 $trips=$db->query('SELECT t.*,h.primary_identifier horse,tr.primary_identifier trailer,d.full_name driver,u.full_name requester FROM fleet_trips t JOIN assets h ON h.id=t.horse_asset_id LEFT JOIN assets tr ON tr.id=t.trailer_asset_id JOIN drivers d ON d.id=t.driver_id JOIN users u ON u.id=t.requested_by ORDER BY t.requested_at DESC,t.id DESC LIMIT 300')->fetchAll();
 $canReview=fleet_cert_user_can($user,'trips.approve');foreach($trips as &$trip)$trip['can_decide']=$canReview&&(int)$trip['requested_by']!==(int)$user['id'];unset($trip);
 json_response(['ok'=>true,'teams'=>$teams,'trips'=>$trips,'can_manage'=>fleet_cert_user_can($user,'trips.manage'),'can_review'=>$canReview,'can_request'=>fleet_cert_user_can($user,'trips.request')]);
}catch(Throwable $e){error_log('Trips data: '.$e->getMessage());json_response(['ok'=>false,'message'=>'Trip data could not be loaded.'],500);}
